/**
 * Definition for singly-linked list.
 * class ListNode {
 *     val: number
 *     next: ListNode | null
 * }
 */
// 分治：兩兩合併，像合併排序一樣往上合
// 時間複雜度: O(N log k)，N 為總節點數；空間複雜度: O(log k)
function mergeKLists(lists) {
    const mergeTwo = (a, b) => {
        const dummy = new ListNode(0);
        let tail = dummy;
        while (a && b) {
            if (a.val <= b.val) {
                tail.next = a;
                a = a.next;
            }
            else {
                tail.next = b;
                b = b.next;
            }
            tail = tail.next;
        }
        tail.next = a ?? b;
        return dummy.next;
    };
    const solve = (lo, hi) => {
        if (lo > hi)
            return null;
        if (lo === hi)
            return lists[lo];
        const mid = (lo + hi) >> 1;
        return mergeTwo(solve(lo, mid), solve(mid + 1, hi));
    };
    return solve(0, lists.length - 1);
}

solutions.cpp:
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */

class Solution {
public:
    /**
     * 方法一：最小堆積
     * 時間複雜度: O(N log k)
     * 空間複雜度: O(k)
     */
    ListNode* mergeKLists(vector<ListNode*>& lists) {
        // 自定義比較器：最小堆積
        auto cmp = [](ListNode* a, ListNode* b) {
            return a->val > b->val;
        };

        priority_queue<ListNode*, vector<ListNode*>, decltype(cmp)> pq(cmp);

        // 將每個鏈表的頭節點加入堆積
        for (ListNode* node : lists) {
            if (node != nullptr) {
                pq.push(node);
            }
        }

        // 虛擬頭節點
        ListNode* dummy = new ListNode(0);
        ListNode* current = dummy;

        // 從堆積中逐個取出最小節點
        while (!pq.empty()) {
            ListNode* node = pq.top();
            pq.pop();

            current->next = node;
            current = current->next;

            // 如果該節點有下一個節點，加入堆積
            if (node->next != nullptr) {
                pq.push(node->next);
            }
        }

        return dummy->next;
    }
};

