solutions.c:
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */
// 分治：兩兩合併，像合併排序一樣往上合
// 時間複雜度: O(N log k)，N 為總節點數；空間複雜度: O(log k)
static struct ListNode* mergeTwo(struct ListNode* a, struct ListNode* b) {
    struct ListNode dummy = {0, NULL};
    struct ListNode* tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) { tail->next = a; a = a->next; }
        else { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

static struct ListNode* solve(struct ListNode** lists, int lo, int hi) {
    if (lo > hi) return NULL;
    if (lo == hi) return lists[lo];
    int mid = lo + (hi - lo) / 2;
    return mergeTwo(solve(lists, lo, mid), solve(lists, mid + 1, hi));
}

struct ListNode* mergeKLists(struct ListNode** lists, int listsSize) {
    return solve(lists, 0, listsSize - 1);
}
